-- FASE D · Bloque 4 · Profetas menores 1
update public.biblical_books
set metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('coverage_status','context_ready'), updated_at=now()
where code in ('HOS','JOL','AMO','OBA');

with source as (select id from public.biblical_sources where slug='vida-contexto-editorial'),
data(slug,book_code,scope_kind,chapter_start,chapter_end,title,summary,historical_context,jewish_context,literary_context,authorial_intent,theological_reflection,interpretive_cautions,key_terms,people_groups,places) as (
values
('oseas-perfil','HOS','book',1,14,'Oseas: pacto, amor herido y retorno','Oseas interpreta la crisis del reino del norte mediante imágenes de pacto, familia, infidelidad, juicio y una persistente invitación al retorno.','El libro se sitúa en las décadas finales de Israel antes de la conquista asiria de Samaria en 722 a. C., dentro de gran inestabilidad política y alianzas internacionales.','Oseas pertenece a los Doce. Sus imágenes de conocimiento de Dios, hesed y retorno influyeron profundamente en la comprensión judía del arrepentimiento.','Alterna relatos simbólicos, acusaciones, memoria histórica, poemas de juicio y súplicas de regreso; la metáfora matrimonial atraviesa varias secciones.','Mostrar que el culto y las alianzas políticas no sustituyen fidelidad, justicia y conocimiento relacional de Dios.','El amor divino confronta el daño sin abandonar el deseo de restaurar; el retorno requiere verdad, responsabilidad y una práctica renovada.','Las metáforas matrimoniales no deben usarse para humillar a mujeres, justificar vigilancia conyugal ni exigir permanencia en abuso. La familia del profeta no es un modelo doméstico normativo.',ARRAY['pacto','hesed','conocimiento de Dios','retorno','Efraín']::text[],ARRAY['israelitas','asirios','sacerdotes']::text[],ARRAY['Samaria','Israel','Asiria']::text[]),
('oseas-1-3-familia','HOS','section',1,3,'Familia simbólica y restauración del pacto','Los nombres de los hijos y la relación familiar funcionan como signos públicos de ruptura, juicio y una futura renovación de la relación de pacto.','Los nombres simbólicos eran una forma profética de interpretar acontecimientos nacionales y dinásticos para una audiencia concreta.','La tradición lee estos capítulos como drama del pacto de Israel; la restauración final evita que la acusación sea la última palabra.','Narración, nombres simbólicos y poesía se entrelazan para mover el texto desde rechazo hacia una nueva promesa de pertenencia.','Hacer visible la gravedad de la infidelidad nacional y afirmar que la disciplina no elimina la posibilidad de reconciliación.','La pertenencia puede ser restaurada sin negar el daño. La gracia no convierte la traición en algo aceptable ni elimina límites protectores.','No debe sexualizarse el lenguaje ni culparse a una esposa por el fracaso nacional. El mandato profético pertenece al relato y no autoriza conductas coercitivas actuales.',ARRAY['Gómer','Jezreel','Lo-ruhama','Lo-ammi','pacto']::text[],ARRAY['familia de Oseas','Israel']::text[],ARRAY['Jezreel','Israel']::text[]),
('oseas-4-11-acusacion','HOS','section',4,11,'Falta de conocimiento, alianzas e historia de amor','Oseas denuncia corrupción sacerdotal, violencia, idolatría y dependencia de imperios, pero recuerda a Israel como un hijo amado llamado desde Egipto.','Israel buscaba sobrevivir entre Asiria y Egipto mientras su vida interna sufría golpes de Estado, desigualdad y prácticas cultuales rivales.','Conocer a Dios significa lealtad y conducta, no simple información. El capítulo 11 transforma la metáfora hacia el amor parental y la compasión.','Acusaciones legales, sátira política y memoria del éxodo culminan en uno de los poemas más tiernos del libro.','Relacionar decadencia política con pérdida de verdad y justicia, y mostrar que la compasión divina resiste la reducción de Dios a ira.','La misericordia puede sostener un llamado firme al cambio. Recordar el cuidado pasado ayuda a recuperar identidad sin idealizarla.','Las críticas cultuales no autorizan desprecio hacia prácticas judías posteriores. Las imágenes de enfermedad y fertilidad son metáforas y no diagnósticos médicos.',ARRAY['conocimiento','sacerdotes','alianzas','Efraín','compasión']::text[],ARRAY['Israel','sacerdotes','asirios','egipcios']::text[],ARRAY['Samaria','Egipto','Asiria']::text[]),
('oseas-12-14-retorno','HOS','section',12,14,'Memoria de Jacob y llamado final al retorno','El libro relee la historia de Jacob, confronta engaño y riqueza injusta y concluye invitando a volver con palabras, abandonar falsos apoyos y recibir sanidad.','El comercio y la política internacional ofrecían señales de prosperidad, pero el profeta las evalúa desde justicia de pacto y memoria histórica.','La liturgia de retorno de Oseas 14 ocupa un lugar importante en la tradición de teshuvá y en lecturas asociadas al arrepentimiento.','Debate histórico, acusación económica y un poema final de sanidad convierten el cierre en una invitación abierta.','Llamar a un arrepentimiento que reconozca palabras, prácticas económicas y dependencias políticas, no solo emociones religiosas.','Volver implica hablar con honestidad, renunciar a sustitutos de seguridad y aprender de nuevo a recibir vida como don.','La promesa de sanar la infidelidad no obliga a víctimas humanas a restablecer relaciones inseguras. El retorno espiritual no sustituye reparación concreta.',ARRAY['Jacob','teshuvá','engaño','riqueza','sanidad','retorno']::text[],ARRAY['Israel','comerciantes','asirios']::text[],ARRAY['Galaad','Betel','Asiria']::text[]),
('joel-perfil','JOL','book',1,3,'Joel: crisis, día de YHWH y Espíritu sobre toda carne','Joel parte de una devastación agrícola para convocar duelo y retorno, reelabora el día de YHWH y anuncia restauración, justicia y derramamiento del Espíritu.','La fecha exacta es debatida; el libro presupone templo y comunidad organizada, pero no nombra un rey. La plaga y sequía reflejan una economía dependiente de cosechas.','Joel integra ayuno, asamblea y oración comunitaria. Su promesa del Espíritu sobre toda carne fue releída en tradiciones judías y cristianas.','Una crisis local se amplía hacia lenguaje cósmico y juicio de naciones, mientras el centro del libro insiste en volver de corazón.','Convertir una emergencia colectiva en llamado a solidaridad, oración y cambio, y sostener que la presencia divina puede alcanzar a toda clase de personas.','La crisis puede abrir espacio para una comunidad más inclusiva, donde edad, género y posición no limitan el don del Espíritu.','No debe declararse que toda plaga o desastre sea castigo identificable. El lenguaje cósmico no ofrece un calendario científico ni permite fijar fechas del fin.',ARRAY['día de YHWH','langostas','retorno','Espíritu','toda carne']::text[],ARRAY['habitantes de Judá','sacerdotes','naciones']::text[],ARRAY['Jerusalén','Sion','valle de Josafat']::text[]),
('joel-1-2-crisis-retorno','JOL','section',1,2,'Devastación, asamblea y promesa de restauración','La pérdida de cosechas lleva a una convocatoria de ancianos, agricultores y sacerdotes; el toque de trompeta anuncia urgencia y el llamado central pide rasgar el corazón.','Una plaga agrícola afectaba alimento, comercio, ofrendas y estabilidad comunitaria. El lenguaje militar intensifica la experiencia sin exigir una identificación única.','Ayuno y asamblea son respuestas comunitarias. La fórmula sobre Dios compasivo y misericordioso conecta Joel con la revelación de Éxodo.','Lamento, descripción de invasión y liturgia de retorno culminan en una respuesta divina de restauración.','Enseñar que una crisis no se resuelve con espectáculo religioso, sino con retorno sincero, cooperación y cuidado de la comunidad vulnerable.','La oración comunitaria puede transformar miedo en responsabilidad compartida. La misericordia no elimina el trabajo de reconstrucción.','Rasgar el corazón no justifica autolesión ni prácticas extremas. Las imágenes de ejército y fuego son poesía profética, no instrucciones violentas.',ARRAY['plaga','ayuno','asamblea','trompeta','corazón','misericordia']::text[],ARRAY['ancianos','agricultores','sacerdotes','niños']::text[],ARRAY['Judá','Sion','Jerusalén']::text[]),
('joel-2-3-espiritu-naciones','JOL','section',2,3,'Espíritu sobre toda carne y justicia entre naciones','Después de restaurar la tierra, el texto anuncia el Espíritu sobre hijos, hijas, ancianos, jóvenes y siervos, y presenta una escena de justicia por violencia y explotación.','La promesa responde a una comunidad pequeña que necesita imaginar futuro más allá de su vulnerabilidad política y económica.','La universalidad interna del don amplía la participación comunitaria. Sion aparece como lugar de refugio y memoria, no como autorización imperial.','Oráculo de salvación, señales cósmicas y juicio de naciones cierran el libro con imágenes de agua y fertilidad.','Afirmar que la presencia divina no queda monopolizada por élites y que la justicia toma en serio la violencia ejercida contra pueblos vulnerables.','Dones y voz pueden aparecer en generaciones y posiciones sociales diversas. La espiritualidad auténtica amplía participación y responsabilidad.','La profecía no autoriza afirmaciones personales infalibles. El juicio de naciones no debe aplicarse a grupos modernos sin evidencia ni utilizarse para promover hostilidad.',ARRAY['Espíritu','hijos e hijas','profecía','Sion','justicia','fuente']::text[],ARRAY['jóvenes','ancianos','siervos','naciones']::text[],ARRAY['Sion','Jerusalén','valle de Josafat']::text[]),
('amos-perfil','AMO','book',1,9,'Amós: justicia, culto y responsabilidad del privilegio','Amós, pastor y cultivador del sur, anuncia en el reino del norte que prosperidad, culto y elección no protegen a una sociedad que explota a pobres y corrompe tribunales.','El ministerio ocurre durante una etapa de riqueza y expansión en el siglo VIII a. C., antes de la conquista asiria. La prosperidad estaba distribuida de forma desigual.','Amós pertenece a los Doce y vincula de manera decisiva culto con justicia. La elección de Israel aumenta responsabilidad en lugar de garantizar inmunidad.','Oráculos contra naciones rodean a Israel, discursos de acusación conducen a visiones y un conflicto en Betel muestra la resistencia institucional.','Exponer la violencia económica oculta detrás de estabilidad religiosa y afirmar que justicia y rectitud son criterios indispensables de fidelidad.','La adoración pierde sentido cuando convive con explotación. Escuchar la voz del pobre forma parte del conocimiento de Dios.','Amós no condena música, reuniones o riqueza por sí mismas; denuncia su separación de justicia. El texto no ofrece una fórmula para culpar individualmente a toda persona pobre o rica.',ARRAY['justicia','rectitud','Betel','pobres','tribunales','día de YHWH']::text[],ARRAY['israelitas','judíos','ricos','pobres','sacerdotes']::text[],ARRAY['Tecoa','Samaria','Betel']::text[]),
('amos-1-2-naciones-israel','AMO','section',1,2,'Círculo de acusaciones y responsabilidad de Israel','Amós denuncia crímenes de pueblos vecinos y, cuando la audiencia espera quedar fuera, dirige la acusación principal contra Judá e Israel por explotación y abuso.','Los oráculos mencionan guerras, deportaciones y trata de poblaciones dentro de conflictos regionales del antiguo Cercano Oriente.','El movimiento retórico impide usar el juicio solo contra enemigos. Israel es evaluado con mayor responsabilidad por su relación de pacto.','La fórmula repetida «por tres y por cuatro» crea un círculo que termina alcanzando a la propia audiencia.','Desarmar la satisfacción de condenar a otros y obligar a la comunidad a examinar sus propias prácticas económicas, sexuales y judiciales.','La autocrítica es una forma de fidelidad. Reconocer privilegio implica escuchar dónde nuestra comodidad depende del daño ajeno.','Los nombres de naciones antiguas no deben transferirse a pueblos modernos. La denuncia de delitos no autoriza odio étnico ni castigo colectivo.',ARRAY['naciones','violencia','deportación','pobres','responsabilidad']::text[],ARRAY['arameos','filisteos','fenicios','edomitas','amonitas','israelitas']::text[],ARRAY['Damasco','Gaza','Tiro','Edom','Samaria']::text[]),
('amos-3-6-culto-injusticia','AMO','section',3,6,'Lujo, tribunales y culto rechazado','Amós confronta casas lujosas, sobornos, deuda, violencia y celebraciones religiosas que continúan mientras el derecho es derribado en la puerta de la ciudad.','Samaria albergaba una élite próspera y redes comerciales, pero el pequeño agricultor podía perder tierra por deuda y decisiones judiciales corruptas.','Buscar a Dios está ligado a buscar el bien. El rechazo de fiestas y cantos se dirige a un culto desconectado de rectitud social.','Discursos de «oíd», lamentos y ayes aumentan la presión hasta la famosa imagen de justicia como corriente permanente.','Mostrar que el privilegio religioso agrava la responsabilidad y que una sociedad no puede compensar abuso mediante ceremonias.','La espiritualidad se prueba en contratos, salarios, tribunales y trato diario. La justicia no es un tema accesorio del culto.','No debe usarse Amós 5 para despreciar la liturgia judía o cristiana. La crítica es ética y contextual, no una abolición de toda forma ritual.',ARRAY['puerta de la ciudad','soborno','lujo','culto','justicia','rectitud']::text[],ARRAY['ricos de Samaria','pobres','jueces','comerciantes']::text[],ARRAY['Samaria','Betel','Gilgal']::text[]),
('amos-7-9-visiones-restauracion','AMO','section',7,9,'Visiones, conflicto en Betel y restauración final','Visiones de langostas, fuego, plomada y fruto de verano anuncian el fin; Amasías intenta expulsar a Amós, y el libro termina con una promesa de restauración y abundancia.','Betel era un santuario real ligado al poder del reino del norte. Cuestionarlo tenía consecuencias políticas además de religiosas.','Amós insiste en que no pertenece a una corporación profética de corte. La restauración final sostiene esperanza más allá del juicio.', 'Visiones breves se alternan con un relato de conflicto y un himno; la conclusión cambia hacia reconstrucción y tierra fértil.','Defender la independencia de la palabra profética frente al poder y afirmar que la crítica busca una comunidad reparada, no destrucción como fin.','La verdad puede venir de fuera de los centros oficiales. La esperanza creíble incluye reconstrucción después de reconocer el daño.','La plomada no permite medir la espiritualidad de otras personas con superioridad. La promesa agrícola no garantiza prosperidad individual ni expansión política moderna.',ARRAY['plomada','Amasías','Betel','profeta','restauración']::text[],ARRAY['Amós','Amasías','casa de Israel']::text[],ARRAY['Betel','Samaria','Judá']::text[]),
('abdias-perfil','OBA','book',1,1,'Abdías: Edom, violencia y el día de YHWH','Abdías denuncia a Edom por orgullo, saqueo y participación en la desgracia de Jerusalén y amplía el caso hacia un día de justicia para las naciones.','El trasfondo más probable es una caída de Jerusalén en la que grupos edomitas aprovecharon la vulnerabilidad de Judá; la identificación exacta del evento es debatida.','La rivalidad entre Edom e Israel se expresa mediante la memoria de Esaú y Jacob, pero el libro evalúa acciones históricas concretas de violencia y traición.','Un breve oráculo se mueve de la caída de Edom a un principio de retribución y luego a restauración de Sion.','Condenar la explotación de una comunidad herida y enseñar que observar, saquear o entregar fugitivos también constituye participación en violencia.','La indiferencia ante el sufrimiento ajeno puede convertirse en complicidad. La justicia exige no aprovecharse de quien ha caído.','Edom antiguo no debe identificarse con una etnia o nación moderna. El texto no autoriza enemistad hereditaria, nacionalismo religioso ni venganza colectiva.',ARRAY['Edom','orgullo','violencia','fugitivos','día de YHWH']::text[],ARRAY['edomitas','judíos','naciones']::text[],ARRAY['Edom','Jerusalén','Sion']::text[]),
('abdias-1-21-juicio-restauracion','OBA','section',1,1,'Orgullo de Edom y restauración de Sion','El poema describe la seguridad geográfica de Edom, enumera su conducta durante la caída de Jerusalén y anuncia una inversión donde la violencia regresa sobre quien la ejerció.','Las fortalezas montañosas y rutas comerciales de Edom podían producir sensación de invulnerabilidad, mientras la caída de Judá ofrecía oportunidades de saqueo.','La relación Esaú-Jacob funciona como memoria de parentesco: precisamente por ser hermano, Edom tenía una responsabilidad especial de no celebrar la calamidad.','La repetición de «no debiste» funciona como acusación ética y conduce al principio «como hiciste, se hará contigo».','Nombrar grados de complicidad y sostener que la soberanía divina juzga tanto la violencia directa como el beneficio obtenido de ella.','La fraternidad exige proteger al vulnerable incluso cuando existen conflictos previos. La restauración no necesita imitar la crueldad del opresor.','La retribución poética no autoriza venganza personal. La restauración de Sion debe leerse en su horizonte antiguo antes de cualquier aplicación política actual.',ARRAY['Esaú','Jacob','hermano','saqueo','retribución','Sion']::text[],ARRAY['edomitas','judíos','fugitivos']::text[],ARRAY['Edom','Jerusalén','Sion']::text[])
)
insert into public.biblical_context_units(slug,book_code,source_id,scope_kind,chapter_start,chapter_end,title,summary,historical_context,jewish_context,literary_context,authorial_intent,theological_reflection,interpretive_cautions,key_terms,people_groups,places,source_locator,provider_version,content_hash,review_status,enabled,metadata)
select d.slug,d.book_code,s.id,d.scope_kind,d.chapter_start,d.chapter_end,d.title,d.summary,d.historical_context,d.jewish_context,d.literary_context,d.authorial_intent,d.theological_reflection,d.interpretive_cautions,d.key_terms,d.people_groups,d.places,'vida://corpus/contexto/profetas-menores/v1#'||d.slug,'profetas-menores-v1-2026-08-02',encode(extensions.digest(concat_ws('|',d.slug,d.title,d.summary,d.historical_context,d.jewish_context,d.literary_context,d.authorial_intent,d.theological_reflection,d.interpretive_cautions),'sha256'),'hex'),'approved',true,jsonb_build_object('coverage_batch','minor-prophets','generated_by_ai',true,'review_level','ai_assisted_editorial','human_review_status','pending','canonical_seed',true)
from data d cross join source s
on conflict(slug) do update set book_code=excluded.book_code,source_id=excluded.source_id,scope_kind=excluded.scope_kind,chapter_start=excluded.chapter_start,chapter_end=excluded.chapter_end,title=excluded.title,summary=excluded.summary,historical_context=excluded.historical_context,jewish_context=excluded.jewish_context,literary_context=excluded.literary_context,authorial_intent=excluded.authorial_intent,theological_reflection=excluded.theological_reflection,interpretive_cautions=excluded.interpretive_cautions,key_terms=excluded.key_terms,people_groups=excluded.people_groups,places=excluded.places,source_locator=excluded.source_locator,provider_version=excluded.provider_version,content_hash=excluded.content_hash,review_status='approved',enabled=true,metadata=excluded.metadata,updated_at=now();